import { appendFileSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { type Config, loadConfig } from "./config.ts";

export type Status = "idle" | "unchanged" | "passed" | "failed";
export type LedgerEntry = { kind: string; [key: string]: unknown };

/** One object shared by every feature in a session. */
export class HarnessState {
  status: Status = "idle";
  planning = false;
  expectChange = false;
  entries: LedgerEntry[] = [];
  private loaded?: { config?: Config; error?: string };
  private cwd?: string;
  private runId = new Date().toISOString().replace(/[:.]/g, "-");

  /** Loaded once, on first use, because extensions only learn the cwd from an event. */
  load(cwd: string) {
    if (this.loaded) return this.loaded;
    this.cwd = cwd;
    try {
      this.loaded = { config: loadConfig(cwd) };
    } catch (error) {
      this.loaded = { error: String(error) };
    }
    return this.loaded;
  }

  /** The harness's own folder ignores itself, so it never looks like a code change. */
  folder(name = "") {
    const root = join(this.cwd ?? process.cwd(), ".openharness");
    mkdirSync(join(root, name), { recursive: true });
    writeFileSync(join(root, ".gitignore"), "*\n");
    return join(root, name);
  }

  record(entry: LedgerEntry) {
    this.entries.push(entry);
    const line = JSON.stringify({ at: new Date().toISOString(), ...entry });
    appendFileSync(join(this.folder("runs"), `${this.runId}.jsonl`), `${line}\n`);
  }
}

policy.code:
/** Decides what a tool call may do. Pure, so it runs anywhere and tests in microseconds. */
export type Tier = "read" | "write" | "exec";
export type Decision = "allow" | "ask" | "deny";
export type Verdict = { decision: Decision; reason: string };
export type Policy = { mode: "ask" | "write" | "yolo"; protect: string[]; frozen?: string[] };
export type Call = { tool: string; input: Record<string, unknown> };

const TIERS: Record<string, Tier> = {
  read: "read", grep: "read", find: "read", ls: "read", read_lines: "read", submit_plan: "read", report: "read",
  write: "write", edit: "write", edit_lines: "write", delegate: "write",
  bash: "exec",
};

/** Never allowed, in any mode. */
const CRITICAL: [RegExp, string][] = [
  [/\bsudo\b/, "runs as root"],
  [/\brm\s+-\w*r\w*\s+(\/|~|\$HOME)(\s|$)/, "deletes a home or root folder"],
  [/\b(curl|wget)\b[^|;&]*\|\s*(ba|z)?sh\b/, "pipes the network into a shell"],
  [/\bgit\s+push\b[^;&|]*\s(--force|-f)\b/, "force-pushes"],
  [/\bgit\s+reset\s+--hard\b/, "throws away work"],
  [/\b(mkfs|shutdown|reboot)\b/, "touches the machine"],
];

/** Unknown tools get the strictest tier, so a new tool is never silently trusted. */
export const tierOf = (tool: string): Tier => TIERS[tool] ?? "exec";

function globToRegExp(glob: string): RegExp {
  const body = glob
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*\*/g, "\0")
    .replace(/\*/g, "[^/]*")
    .replace(/\0/g, ".*");
  return new RegExp(`^${body}$`);
}

/** Resolves . and .. segments. Returns null when the path leaves the project. */
export function normalize(path: string, cwd = ""): string | null {
  const inside = cwd && path.startsWith(`${cwd}/`) ? path.slice(cwd.length + 1) : path;
  if (inside.startsWith("/") || inside.startsWith("~")) return null;
  const parts: string[] = [];
  for (const part of inside.split("/")) {
    if (part === "..") {
      if (!parts.length) return null;
      parts.pop();
    } else if (part && part !== ".") {
      parts.push(part);
    }
  }
  return parts.join("/");
}

export function isProtected(path: string, protect: string[]) {
  const name = path.split("/").pop() ?? path;
  return protect.some((glob) => globToRegExp(glob).test(glob.includes("/") ? path : name));
}

export function decide({ tool, input }: Call, policy: Policy, cwd = ""): Verdict {
  const tier = tierOf(tool);

  if (typeof input.path === "string") {
    const path = normalize(input.path, cwd);
    if (path === null && tier !== "read") {
      return { decision: "deny", reason: `${input.path} is outside the project` };
    }
    if (path !== null && isProtected(path, policy.protect)) {
      return { decision: "deny", reason: `${path} is protected` };
    }
    if (path !== null && tier !== "read" && isProtected(path, policy.frozen ?? [])) {
      return { decision: "deny", reason: `${path} is frozen. Find the code it tests and fix that instead` };
    }
  }

  if (tool === "bash") {
    const command = String(input.command ?? "");
    for (const [pattern, why] of CRITICAL) {
      if (pattern.test(command)) return { decision: "deny", reason: `this command ${why}` };
    }
    for (const word of command.split(/[\s"'=;|&<>]+/)) {
      const path = word && normalize(word, cwd);
      if (path && isProtected(path, policy.protect)) {
        return { decision: "deny", reason: `the command mentions ${path}, which is protected` };
      }
    }
  }

  const free = policy.mode === "yolo" || tier === "read" || (policy.mode === "write" && tier === "write");
  return free
    ? { decision: "allow", reason: `${tier} is allowed in ${policy.mode} mode` }
    : { decision: "ask", reason: `${tier} needs approval in ${policy.mode} mode` };
}

guard.code:
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { decide, tierOf } from "../policy.ts";
import type { HarnessState } from "../state.ts";

export function installGuard(pi: ExtensionAPI, state: HarnessState) {
  pi.on("tool_call", async (event, ctx) => {
    const { config, error } = state.load(ctx.cwd);

    // Fail closed: with a broken policy file, only reads get through.
    if (!config) {
      if (tierOf(event.toolName) === "read") return undefined;
      return { block: true, reason: `Blocked: ${error}` };
    }

    const verdict = decide({ tool: event.toolName, input: event.input }, config, ctx.cwd);
    if (verdict.decision === "allow") return undefined;

    if (verdict.decision === "ask" && ctx.hasUI) {
      const yes = await ctx.ui.confirm("OpenHarness", `${event.toolName}: ${verdict.reason}. Allow it?`);
      if (yes) return undefined;
    }

    state.record({ kind: "blocked", tool: event.toolName, reason: verdict.reason });
    return { block: true, reason: `Blocked by OpenHarness: ${verdict.reason}.` };
  });
}

hashline.code:
/** Every line gets an anchor like 12#a3f1, its number plus a hash of its text. */
export type Edit = { from: string; to?: string; lines: string[] } | { after: string; lines: string[] };

export class StaleAnchor extends Error {}

/** FNV-1a, folded to 16 bits. Small, fast, and identical on every platform. */
export function lineHash(line: string) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < line.length; i++) {
    hash ^= line.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return ((hash ^ (hash >>> 16)) & 0xffff).toString(16).padStart(4, "0");
}

const split = (text: string) => {
  const lines = text.split("\n");
  if (lines.at(-1) === "") lines.pop();
  return lines;
};

export function render(text: string, offset = 1, limit = 400) {
  return split(text)
    .map((line, index) => `${index + 1}#${lineHash(line)}|${line}`)
    .slice(offset - 1, offset - 1 + limit)
    .join("\n");
}

/** Returns the zero-based index an anchor points to, or throws if the file moved on. */
function resolve(anchor: string, lines: string[]) {
  const match = anchor.match(/^(\d+)#([0-9a-f]{4})$/);
  if (!match) throw new StaleAnchor(`"${anchor}" is not an anchor. Use the form 12#a3f1.`);
  const index = Number(match[1]) - 1;
  if (index < 0 || index >= lines.length || lineHash(lines[index]) !== match[2]) {
    throw new StaleAnchor(`${anchor} is stale. Read the file again before editing.`);
  }
  return index;
}

/** All anchors are checked before anything changes, so a bad edit leaves no trace. */
export function applyEdits(text: string, edits: Edit[]) {
  const lines = split(text);
  const spans = edits.map((edit) => {
    if ("after" in edit) {
      const at = edit.after === "0" ? 0 : resolve(edit.after, lines) + 1;
      return { start: at, end: at, lines: edit.lines };
    }
    const start = resolve(edit.from, lines);
    const end = edit.to ? resolve(edit.to, lines) + 1 : start + 1;
    if (end <= start) throw new StaleAnchor(`${edit.to} comes before ${edit.from}.`);
    return { start, end, lines: edit.lines };
  });

  const ordered = spans.sort((a, b) => b.start - a.start);
  ordered.forEach((span, index) => {
    const next = ordered[index - 1];
    if (next && span.end > next.start) throw new StaleAnchor("Two edits overlap.");
  });
  for (const span of ordered) lines.splice(span.start, span.end - span.start, ...span.lines);

  return lines.join("\n") + (text.endsWith("\n") || !text ? "\n" : "");
}

