#!/usr/bin/env node
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ModelRuntime } from "@earendil-works/pi-coding-agent";
import { defaults } from "../src/config.ts";
import { summarize } from "../src/features/ledger.ts";
import { createHarness } from "../src/harness.ts";

const [command, ...rest] = process.argv.slice(2);
const cwd = process.cwd();

function flag(name: string) {
  const index = rest.indexOf(name);
  return index < 0 ? undefined : rest.splice(index, 2)[1];
}

async function run() {
  const wanted = flag("--model");
  const modelRuntime = await ModelRuntime.create();
  const [provider, ...id] = wanted?.split("/") ?? [];
  const model = provider ? modelRuntime.getModel(provider, id.join("/")) : undefined;
  if (wanted && !model) throw new Error(`Unknown model: ${wanted}`);

  const harness = await createHarness({ cwd, model, modelRuntime });
  const summary = await harness.run(rest.join(" "));
  harness.session.dispose();
  console.log(JSON.stringify(summary, null, 2));
  process.exitCode = summary.status === "passed" ? 0 : 1;
}

function report() {
  const folder = join(cwd, ".openharness/runs");
  const last = existsSync(folder) ? readdirSync(folder).sort().at(-1) : undefined;
  if (!last) throw new Error("No runs yet.");
  const lines = readFileSync(join(folder, last), "utf8").trim().split("\n");
  console.log(JSON.stringify(summarize(lines.map((line) => JSON.parse(line))), null, 2));
}

function init() {
  const file = join(cwd, "harness.json");
  if (existsSync(file)) throw new Error("harness.json already exists.");
  writeFileSync(file, `${JSON.stringify({ ...defaults, verify: ["npm test"] }, null, 2)}\n`);
  console.log("Wrote harness.json. Set verify to your project's checks.");
}

const commands: Record<string, () => void | Promise<void>> = { init, run, report };
const chosen = commands[command];
if (!chosen) {
  console.log('usage: openharness init | run "<task>" [--model provider/id] | report');
  process.exit(2);
}
try {
  await chosen();
} catch (error) {
  console.error(`openharness: ${(error as Error).message}`);
  process.exit(1);
}

