import assert from "node:assert/strict";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";
import { setTimeout } from "node:timers/promises";
import { fauxAssistantMessage as say, fauxToolCall as call } from "@earendil-works/pi-ai";
import { lineHash } from "../src/hashline.ts";
import { scripted, sandbox } from "./helpers.ts";

const BUG = "export const add = (a, b) => a - b;";
const STILL_WRONG = "export const add = (a, b) => a * b + 1;";
const FIXED = "export const add = (a, b) => a + b;";
const edit = (from: string, to: string) =>
  say(call("edit_lines", { path: "math.js", edits: [{ from: `1#${lineHash(from)}`, lines: [to] }] }));
const ship = say(call("report", { verdict: "ship", findings: [] }));
const text = (path: string, cwd: string) => readFileSync(join(cwd, path), "utf8");

test("the verify gate refuses to finish until the checks pass", async () => {
  const { cwd } = sandbox();
  const h = await scripted(cwd);
  h.faux.setResponses([edit(BUG, STILL_WRONG), say("Done!"), edit(STILL_WRONG, FIXED), say("Done now."), ship, say("Summary.")]);

  const result = await h.run("fix add");

  assert.equal(result.status, "passed");
  assert.equal(result.verifyFailures, 1);
  assert.equal(result.reviews, 1);
  assert.equal(text("math.js", cwd), `${FIXED}\n`);
  h.session.dispose();
});

test("a model that never fixes it runs out of retries and fails", async () => {
  const { cwd } = sandbox({ maxRetries: 1 });
  const h = await scripted(cwd);
  h.faux.setResponses([edit(BUG, STILL_WRONG), say("Done!"), say("Still done!")]);

  const result = await h.run("fix add");

  assert.equal(result.status, "failed");
  assert.equal(result.verifyFailures, 2);
  h.session.dispose();
});

test("the failing output reaches the model", async () => {
  const { cwd } = sandbox();
  const h = await scripted(cwd);
  let seen = "";
  h.faux.setResponses([
    edit(BUG, STILL_WRONG),
    say("Done!"),
    (context) => {
      seen = JSON.stringify(context.messages.at(-1));
      return edit(STILL_WRONG, FIXED);
    },
    say("Fixed."),
    ship,
    say("Summary."),
  ]);

  await h.run("fix add");

  assert.match(seen, /add\(2, 2\) should be 4/);
  h.session.dispose();
});

test("review can send the work back", async () => {
  const { cwd } = sandbox();
  const h = await scripted(cwd);
  const finding = { priority: "P1", file: "math.js", issue: "No test for negatives." };
  h.faux.setResponses([
    edit(BUG, FIXED),
    say("Done."),
    say(call("report", { verdict: "fix", findings: [finding] })),
    say(call("write", { path: "negatives.js", content: "// covered\n" })),
    say("Added."),
    ship,
    say("Summary."),
  ]);

  const result = await h.run("fix add");

  assert.equal(result.status, "passed");
  assert.equal(result.reviews, 2);
  h.session.dispose();
});

test("a reviewer that never reports fails the run, not passes it", async () => {
  const { cwd } = sandbox();
  const h = await scripted(cwd);
  h.faux.setResponses([edit(BUG, FIXED), say("Done."), say("Looks fine to me, no report.")]);

  const result = await h.run("fix add");

  assert.equal(result.status, "failed");
  h.session.dispose();
});

test("a typo in the review model fails, it does not fall back", async () => {
  const { cwd } = sandbox({ review: { model: "nobody/nothing" } });
  const h = await scripted(cwd);
  h.faux.setResponses([edit(BUG, FIXED), say("Done.")]);

  const result = await h.run("fix add");

  assert.equal(result.status, "failed");
  h.session.dispose();
});

test("a frozen check cannot be edited, but it can be read", async () => {
  const { cwd } = sandbox({ frozen: ["check.js"] });
  const h = await scripted(cwd);
  h.faux.setResponses([
    say(call("read_lines", { path: "check.js" })),
    say(call("write", { path: "check.js", content: "// gone\n" })),
    say("OK."),
  ]);

  const result = await h.run("fix add", { expectChange: false });

  assert.equal(result.blocked, 1);
  assert.equal(result.toolErrors, 1, "only the write fails");
  assert.match(text("check.js", cwd), /should be 4/);
  h.session.dispose();
});

test("rewriting a frozen check through bash is undone and sent back", async () => {
  const { cwd } = sandbox({ mode: "yolo", frozen: ["check.js"] });
  const h = await scripted(cwd);
  let told = "";
  h.faux.setResponses([
    say(call("bash", { command: "echo 'console.log(1)' > check.js" })),
    say("All green!"),
    (context) => {
      told = JSON.stringify(context.messages.at(-1));
      return edit(BUG, FIXED);
    },
